// Package artifact implements the M3 download artifact store: files generated by
// pack exports are registered with a 24h TTL, tracked in an atomically written
// 0600 artifacts.json index and served from GET /api/artifacts/{id}.
//
// Contract: docs/M3_INTERFACES.md `4, docs/IMPLEMENTATION_SPEC.md `3.4/`4.2.
// Files and the index live in one directory (cache/exports). The index is
// replaced atomically and every path accepted by Add must stay inside that
// directory, so a download can never escape it. Expired entries are hidden by
// Get and deleted by Cleanup (Add also prunes expired entries first).
package artifact

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"mime"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"
)

const (
	// TTL is how long a registered artifact stays downloadable.
	TTL = 24 * time.Hour

	// schemaVersion is the artifacts.json schema version.
	schemaVersion = 1

	// metadataFilename is the persisted index file inside the store directory.
	metadataFilename = "artifacts.json"

	// defaultContentType is used when Add receives an empty content type.
	defaultContentType = "application/octet-stream"

	// maxFilenameBytes bounds the download filename header value.
	maxFilenameBytes = 255
)

// artifactIDPattern matches a canonical artifact id: 12 lowercase hex digits.
var artifactIDPattern = regexp.MustCompile("^[0-9a-f]{12}$")

// Artifact is one registered downloadable file.
type Artifact struct {
	ID          string `json:"id"`
	Filename    string `json:"filename"`
	Path        string `json:"path"`
	ContentType string `json:"contentType"`
	Size        int64  `json:"size"`
	CreatedAt   int64  `json:"createdAt"` // milliseconds
	ExpiresAt   int64  `json:"expiresAt"` // milliseconds
}

// Store is the artifact index and download handler. It is safe for concurrent
// use.
type Store struct {
	dir     string // store directory as given to Open (absolute)
	realDir string // symlink-resolved store directory used for containment checks

	// now is the clock used for TTL decisions; tests replace it.
	now func() time.Time

	mu        sync.Mutex
	artifacts map[string]Artifact
}

// storeFile is the persisted artifacts.json document
// (docs/IMPLEMENTATION_SPEC.md `3.4).
type storeFile struct {
	SchemaVersion int             `json:"schemaVersion"`
	Artifacts     []storeArtifact `json:"artifacts"`
}

// storeArtifact is one entry of the persisted index.
type storeArtifact struct {
	ID          string `json:"id"`
	Filename    string `json:"filename"`
	Path        string `json:"path"`
	Size        int64  `json:"size"`
	ContentType string `json:"contentType"`
	ExpiresAt   int64  `json:"expiresAt"`
}

// Open opens (or creates) the artifact store rooted at dir, typically
// <data-root>/cache/exports. A missing directory is created with 0700; an
// existing artifacts.json must carry schemaVersion 1. Unsafe or corrupt entries
// are dropped (and the cleaned index is persisted); a corrupt index is reported
// as an error and never overwritten.
func Open(dir string) (*Store, error) {
	if strings.TrimSpace(dir) == "" {
		return nil, errors.New("artifact: 存储目录不能为空")
	}
	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, fmt.Errorf("artifact: 解析存储目录绝对路径失败: %w", err)
	}
	if err := os.MkdirAll(abs, 0o700); err != nil {
		return nil, fmt.Errorf("artifact: 创建存储目录 %s 失败: %w", abs, err)
	}
	info, err := os.Lstat(abs)
	if err != nil {
		return nil, fmt.Errorf("artifact: 检查存储目录 %s 失败: %w", abs, err)
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("artifact: 存储路径 %s 不是目录", abs)
	}
	realDir, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return nil, fmt.Errorf("artifact: 解析存储目录真实路径失败: %w", err)
	}
	s := &Store{
		dir:       abs,
		realDir:   realDir,
		now:       time.Now,
		artifacts: make(map[string]Artifact),
	}
	if err := s.load(); err != nil {
		return nil, err
	}
	return s, nil
}

// load reads and validates artifacts.json. It is called once from Open before
// the store is shared, so it does not take the lock.
func (s *Store) load() error {
	path := filepath.Join(s.dir, metadataFilename)
	info, err := os.Lstat(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return fmt.Errorf("artifact: 检查 %s 失败: %w", metadataFilename, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return fmt.Errorf("artifact: %s 必须是普通文件", metadataFilename)
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("artifact: 读取 %s 失败: %w", metadataFilename, err)
	}
	var file storeFile
	if err := json.Unmarshal(raw, &file); err != nil {
		return fmt.Errorf("artifact: 解析 %s 失败: %w", metadataFilename, err)
	}
	if file.SchemaVersion != schemaVersion {
		return fmt.Errorf("artifact: %s schemaVersion=%d 不受支持（期望 %d）", metadataFilename, file.SchemaVersion, schemaVersion)
	}
	dropped := 0
	for _, entry := range file.Artifacts {
		art := Artifact{
			ID:          entry.ID,
			Filename:    entry.Filename,
			Path:        entry.Path,
			ContentType: entry.ContentType,
			Size:        entry.Size,
			ExpiresAt:   entry.ExpiresAt,
			CreatedAt:   entry.ExpiresAt - int64(TTL/time.Millisecond),
		}
		if err := s.validateLoaded(art); err != nil {
			dropped++
			continue
		}
		s.artifacts[art.ID] = art
	}
	if dropped > 0 {
		// Self-heal: never keep entries that could point outside the store.
		if err := s.persistLocked(); err != nil {
			return err
		}
	}
	return nil
}

// validateLoaded checks one entry read from artifacts.json.
func (s *Store) validateLoaded(art Artifact) error {
	if !artifactIDPattern.MatchString(art.ID) {
		return errors.New("非法 artifact id")
	}
	if err := validateFilename(art.Filename); err != nil {
		return err
	}
	if _, err := normalizeContentType(art.ContentType); err != nil {
		return err
	}
	if art.Size < 0 || art.ExpiresAt <= 0 {
		return errors.New("非法 artifact 元数据")
	}
	if !filepath.IsAbs(art.Path) || (!s.containsPath(art.Path) && !s.containsRealPath(art.Path)) {
		return errors.New("artifact 路径不在存储目录内")
	}
	return nil
}

// Add registers a file under the store directory and returns its artifact
// metadata. The id is 12 lowercase hex digits and the entry expires 24h after
// creation; expired entries are pruned first. The index is persisted with an
// atomic 0600 write before Add returns.
//
// filename is the download name (no path separators or control characters);
// path must be an absolute path to an existing regular file inside the store
// directory; contentType defaults to application/octet-stream; size must match
// the file size (0 means "read it from disk").
func (s *Store) Add(filename, path, contentType string, size int64) (Artifact, error) {
	filename = strings.TrimSpace(filename)
	if err := validateFilename(filename); err != nil {
		return Artifact{}, err
	}
	realPath, err := s.resolveArtifactPath(path)
	if err != nil {
		return Artifact{}, err
	}
	info, err := os.Lstat(realPath)
	if err != nil {
		return Artifact{}, fmt.Errorf("artifact: 检查文件 %s 失败: %w", realPath, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return Artifact{}, fmt.Errorf("artifact: %s 必须是普通文件", realPath)
	}
	if size < 0 {
		return Artifact{}, errors.New("artifact: 文件大小不能为负数")
	}
	if size == 0 {
		size = info.Size()
	}
	if size != info.Size() {
		return Artifact{}, fmt.Errorf("artifact: 文件大小不一致（登记 %d，实际 %d）", size, info.Size())
	}
	contentType, err = normalizeContentType(contentType)
	if err != nil {
		return Artifact{}, err
	}

	now := s.now()
	s.mu.Lock()
	defer s.mu.Unlock()
	// Re-registering the same file replaces older entries for that path; the
	// shared file must survive the replacement (and later cleanups).
	for existingID, existing := range s.artifacts {
		if existing.Path == realPath {
			delete(s.artifacts, existingID)
		}
	}
	s.pruneExpiredLocked(now)

	id, err := s.newIDLocked()
	if err != nil {
		return Artifact{}, err
	}
	art := Artifact{
		ID:          id,
		Filename:    filename,
		Path:        realPath,
		ContentType: contentType,
		Size:        size,
		CreatedAt:   now.UnixMilli(),
		ExpiresAt:   now.Add(TTL).UnixMilli(),
	}
	s.artifacts[art.ID] = art
	if err := s.persistLocked(); err != nil {
		delete(s.artifacts, art.ID)
		return Artifact{}, err
	}
	return art, nil
}

// Get returns the artifact metadata when id exists and has not expired yet.
func (s *Store) Get(id string, now time.Time) (Artifact, bool) {
	s.mu.Lock()
	art, ok := s.artifacts[id]
	s.mu.Unlock()
	if !ok {
		return Artifact{}, false
	}
	if now.UnixMilli() >= art.ExpiresAt {
		return Artifact{}, false
	}
	return art, true
}

// Cleanup removes expired entries and their files, persisting the index when
// something changed.
func (s *Store) Cleanup(now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if removed := s.pruneExpiredLocked(now); removed == 0 {
		return nil
	}
	return s.persistLocked()
}

// pruneExpiredLocked removes expired entries and best-effort deletes their
// files. The caller must hold s.mu.
func (s *Store) pruneExpiredLocked(now time.Time) int {
	nowMs := now.UnixMilli()
	removed := 0
	for id, art := range s.artifacts {
		if nowMs < art.ExpiresAt {
			continue
		}
		delete(s.artifacts, id)
		removed++
		if s.containsPath(art.Path) {
			if err := os.Remove(art.Path); err != nil && !errors.Is(err, fs.ErrNotExist) {
				// Metadata is already dropped; a leftover file is harmless and
				// best-effort cleanup must not fail the store.
				continue
			}
		}
	}
	return removed
}

// resolveArtifactPath validates path and returns its symlink-resolved absolute
// form, guaranteeing the real file stays inside the store directory.
func (s *Store) resolveArtifactPath(path string) (string, error) {
	path = strings.TrimSpace(path)
	if path == "" {
		return "", errors.New("artifact: 文件路径不能为空")
	}
	if !filepath.IsAbs(path) {
		return "", fmt.Errorf("artifact: 文件路径必须是绝对路径: %s", path)
	}
	clean := filepath.Clean(path)
	if !s.containsPath(clean) {
		return "", fmt.Errorf("artifact: 文件必须位于存储目录内: %s", clean)
	}
	info, err := os.Lstat(clean)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return "", fmt.Errorf("artifact: 文件不存在: %s", clean)
		}
		return "", fmt.Errorf("artifact: 检查文件路径失败: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		// docs/IMPLEMENTATION_SPEC.md §5: artifact paths must reject symlinks.
		return "", fmt.Errorf("artifact: 不允许符号链接: %s", clean)
	}
	realPath, err := filepath.EvalSymlinks(clean)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return "", fmt.Errorf("artifact: 文件不存在: %s", clean)
		}
		return "", fmt.Errorf("artifact: 解析文件真实路径失败: %w", err)
	}
	if !s.containsRealPath(realPath) {
		return "", fmt.Errorf("artifact: 文件真实路径不在存储目录内: %s", realPath)
	}
	return realPath, nil
}

// containsPath reports whether path is a lexical descendant of the store dir.
func (s *Store) containsPath(path string) bool {
	return pathWithin(s.dir, path)
}

// containsRealPath reports whether the symlink-resolved path stays in the real
// store directory.
func (s *Store) containsRealPath(path string) bool {
	return pathWithin(s.realDir, path)
}

// pathWithin reports whether path is strictly below dir (dir itself is not a
// file artifact).
func pathWithin(dir, path string) bool {
	rel, err := filepath.Rel(dir, path)
	if err != nil || rel == "." || filepath.IsAbs(rel) {
		return false
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return false
	}
	return true
}

// newIDLocked returns an unused 12 lowercase hex digit id. The caller must hold
// s.mu.
func (s *Store) newIDLocked() (string, error) {
	for attempt := 0; attempt < 8; attempt++ {
		id, err := newArtifactID()
		if err != nil {
			return "", err
		}
		if _, exists := s.artifacts[id]; !exists {
			return id, nil
		}
	}
	return "", errors.New("artifact: 生成唯一 artifact id 失败")
}

// newArtifactID returns a fresh 12 lowercase hex digit id.
func newArtifactID() (string, error) {
	var raw [6]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", fmt.Errorf("artifact: 生成 artifact id 失败: %w", err)
	}
	return hex.EncodeToString(raw[:]), nil
}

// persistLocked writes artifacts.json atomically (0600). The caller must hold
// s.mu.
func (s *Store) persistLocked() error {
	ids := make([]string, 0, len(s.artifacts))
	for id := range s.artifacts {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(a, b int) bool {
		left, right := s.artifacts[ids[a]], s.artifacts[ids[b]]
		if left.CreatedAt != right.CreatedAt {
			return left.CreatedAt < right.CreatedAt
		}
		return left.ID < right.ID
	})
	file := storeFile{
		SchemaVersion: schemaVersion,
		Artifacts:     make([]storeArtifact, 0, len(ids)),
	}
	for _, id := range ids {
		art := s.artifacts[id]
		file.Artifacts = append(file.Artifacts, storeArtifact{
			ID:          art.ID,
			Filename:    art.Filename,
			Path:        art.Path,
			Size:        art.Size,
			ContentType: art.ContentType,
			ExpiresAt:   art.ExpiresAt,
		})
	}
	raw, err := json.Marshal(file)
	if err != nil {
		return fmt.Errorf("artifact: 编码 %s 失败: %w", metadataFilename, err)
	}
	return atomicWriteFile(filepath.Join(s.dir, metadataFilename), raw, 0o600)
}

// atomicWriteFile writes data to path with a same-directory temporary file,
// fsync and rename, then fsyncs the directory.
func atomicWriteFile(path string, data []byte, perm os.FileMode) error {
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return fmt.Errorf("artifact: 创建临时文件失败: %w", err)
	}
	tmpName := tmp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = tmp.Close()
			_ = os.Remove(tmpName)
		}
	}()
	if err := tmp.Chmod(perm); err != nil {
		return fmt.Errorf("artifact: 设置临时文件权限失败: %w", err)
	}
	if _, err := tmp.Write(data); err != nil {
		return fmt.Errorf("artifact: 写入临时文件失败: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		return fmt.Errorf("artifact: 同步临时文件失败: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("artifact: 关闭临时文件失败: %w", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("artifact: 替换 %s 失败: %w", filepath.Base(path), err)
	}
	cleanup = false
	if d, err := os.Open(dir); err == nil {
		_ = d.Sync()
		_ = d.Close()
	}
	return nil
}

// validateFilename rejects download names that are empty, too long, contain
// path separators or control characters (which could also inject headers).
func validateFilename(name string) error {
	if name == "" {
		return errors.New("artifact: 文件名不能为空")
	}
	if len(name) > maxFilenameBytes {
		return fmt.Errorf("artifact: 文件名超长（%d 字节，上限 %d）", len(name), maxFilenameBytes)
	}
	if name == "." || name == ".." {
		return errors.New("artifact: 文件名非法")
	}
	if strings.ContainsAny(name, "/\\") {
		return errors.New("artifact: 文件名不能包含路径分隔符")
	}
	for _, r := range name {
		if r < 0x20 || r == 0x7f {
			return errors.New("artifact: 文件名不能包含控制字符")
		}
	}
	return nil
}

// normalizeContentType validates a Content-Type header value and applies the
// documented default when it is empty.
func normalizeContentType(contentType string) (string, error) {
	contentType = strings.TrimSpace(contentType)
	if contentType == "" {
		return defaultContentType, nil
	}
	if strings.ContainsAny(contentType, "\r\n") {
		return "", errors.New("artifact: Content-Type 非法")
	}
	mediaType, _, err := mime.ParseMediaType(contentType)
	if err != nil || mediaType == "" {
		return "", fmt.Errorf("artifact: Content-Type 非法: %q", contentType)
	}
	return contentType, nil
}
